# Dockerfile: install pinned rsgain 3.7 Bookworm package and smoke test it.
p=Path('Dockerfile'); s=p.read_text()
needle='''    && rm -rf /var/lib/apt/lists/*\n\nCOPY --from=sox-ultra-builder /stage/opt/sox-ultra /opt/sox-ultra\n'''
replacement='''    && rm -rf /var/lib/apt/lists/*\n\nARG RSGAIN_VERSION=3.7\nRUN curl -fsSL "https://github.com/complexlogic/rsgain/releases/download/v${RSGAIN_VERSION}/rsgain_${RSGAIN_VERSION}-1_amd64.deb" -o /tmp/rsgain.deb \\\n    && apt-get update \\\n    && apt-get install -y --no-install-recommends /tmp/rsgain.deb \\\n    && rm -f /tmp/rsgain.deb \\\n    && rm -rf /var/lib/apt/lists/* \\\n    && rsgain --version\n\nCOPY --from=sox-ultra-builder /stage/opt/sox-ultra /opt/sox-ultra\n'''
if s.count(needle)!=1: raise SystemExit(f'Docker insertion count={s.count(needle)}')
s=s.replace(needle,replacement,1)
s=s.replace('    && /opt/sox-ultra/bin/sox --version \\\n', '    && /opt/sox-ultra/bin/sox --version \\\n    && rsgain --version \\\n', 1)
p.write_text(s)
